import * as THREE from 'three';
import {GLTFLoader} from 'three/addons/loaders/GLTFLoader.js';
import {OrbitControls} from 'three/addons/controls/OrbitControls.js';
const $=id=>document.getElementById(id),canvas=$('portrait'),status=$('status');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1;
const scene=new THREE.Scene();scene.background=new THREE.Color('#e0e7df');
const ambient=new THREE.HemisphereLight('#fffaf2','#9da9a4',2);scene.add(ambient);const key=new THREE.DirectionalLight('#fff6eb',2.5);key.position.set(-3,4,5);scene.add(key);const fill=new THREE.DirectionalLight('#e5efff',.7);fill.position.set(3,2,3);scene.add(fill);
const camera=new THREE.OrthographicCamera(-.35,.35,.35,-.35,.01,20),controls=new OrbitControls(camera,canvas);controls.enableDamping=true;controls.minZoom=.4;controls.maxZoom=3;controls.enablePan=true;
let model=null,mixer=null,actions={},playing=false,whole=false,angle=-.16,pitch=0,ready=false,sequence=0,version='director-v15',clay=false;const clayMaterial=new THREE.MeshStandardMaterial({color:'#c9b6a0',roughness:.9});
const isAnatomy=()=>['director-v07','director-v08','director-v09','director-v10','director-v11','director-v12','director-v13','director-v14','director-v15'].includes(version);
// Match the unmodified reference image's scale and crop for the v13 photo view.
function referenceFrame(){const factor=matchMedia('(max-width:700px)').matches?1.5:1.7,top=factor===1.5?0:-.05,scale=.6165579074688895,ppw=602/.65,half=scale*1850/(2*factor*ppw);return {half,x:.018+(scale*692-198.28374888919961-236)/ppw,y:1.26+(301+80.18638390174533)/ppw-2*half*(.5-top)};}
function framingLabel(){return whole?(isAnatomy()?'看頭型':'看五官'):(isAnatomy()?'看完整胸像':'看全身');}
function resize(){const {width,height}=canvas.getBoundingClientRect(),aspect=width/Math.max(1,height),half=whole?(isAnatomy()?.44:.91):(['director-v13','director-v14','director-v15'].includes(version)?referenceFrame().half:Math.max(version==='director-v12'?.365:.325,.23/aspect));renderer.setSize(Math.max(1,width),Math.max(1,height),false);camera.left=-half*aspect;camera.right=half*aspect;camera.top=half;camera.bottom=-half;camera.updateProjectionMatrix();}
function reset(){camera.zoom=1;const frame=['director-v13','director-v14','director-v15'].includes(version)?referenceFrame():{x:.018,y:version==='director-v12'?1.28:1.26};controls.target.set(whole?0:frame.x,whole?(isAnatomy()?1.14:.8):frame.y,0);camera.position.set(whole?0:frame.x,(whole?(isAnatomy()?1.14:.8):frame.y)+4*Math.sin(pitch),4*Math.cos(pitch));if(model)model.rotation.y=angle;controls.update();resize();}
function setAngle(value){pitch=0;$('top-view').setAttribute('aria-pressed','false');angle=value;reset();document.querySelectorAll('[data-angle]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.angle)===value)));}
function stopMotion(){playing=false;mixer?.stopAllAction();$('motion').setAttribute('aria-pressed','false');$('motion').textContent='播放揮手';}
function disposeModel(root){root.traverse(o=>{if(!o.isMesh)return;if(o.userData.studyMaterial)o.material=o.userData.studyMaterial;o.geometry.dispose();for(const m of (Array.isArray(o.material)?o.material:[o.material])){for(const v of Object.values(m))if(v?.isTexture)v.dispose();m.dispose();}});scene.remove(root);}
async function load(){const ticket=++sequence;ready=false;stopMotion();status.hidden=false;status.textContent='正在載入角色…';$('capture').disabled=true;version=$('version').value;ambient.intensity=['director-v12','director-v13','director-v14','director-v15'].includes(version)?2.8:2;key.intensity=['director-v12','director-v13','director-v14','director-v15'].includes(version)?1.1:2.5;fill.intensity=['director-v12','director-v13','director-v14','director-v15'].includes(version)?1.1:.7;
 try{const gltf=await new GLTFLoader().loadAsync(`assets/characters/${version}/director_wu.glb`);if(ticket!==sequence){disposeModel(gltf.scene);return;}if(model){mixer?.uncacheRoot(model);disposeModel(model);}model=gltf.scene;model.traverse(o=>{if(o.name.startsWith('cast_')){const part=o.name.replace(/^cast_/,'').replace(/_\d+$/,'');o.visible=part==='body'||part==='short';}if(o.isMesh){o.frustumCulled=false;o.userData.studyMaterial=o.material;}});scene.add(model);mixer=new THREE.AnimationMixer(model);actions=Object.fromEntries(gltf.animations.map(clip=>[clip.name.toLowerCase().split('|').at(-1),mixer.clipAction(clip)]));clay=isAnatomy()&&!['director-v09','director-v10','director-v11','director-v12','director-v13','director-v14','director-v15'].includes(version);$('surface').disabled=clay;$('surface').setAttribute('aria-pressed',String(clay));$('surface').textContent=clay?'素模階段':'檢查素模';$('motion').disabled=!actions.wave;$('motion').textContent=actions.wave?'播放揮手':'靜態頭型研究';$('framing').textContent=framingLabel();reset();applySurface();ready=true;status.hidden=true;$('capture').disabled=false;$('version-label').textContent=$('version').selectedOptions[0].textContent;
 }catch(e){if(ticket!==sequence)return;status.textContent='角色載入失敗，請重新整理頁面再試一次。';console.error(e);}}
for(const b of document.querySelectorAll('[data-angle]'))b.onclick=()=>setAngle(Number(b.dataset.angle));
$('top-view').onclick=()=>{whole=false;pitch=1.52;angle=-.16;reset();$('top-view').setAttribute('aria-pressed','true');$('framing').setAttribute('aria-pressed','false');$('framing').textContent=framingLabel();document.querySelectorAll('[data-angle]').forEach(b=>b.setAttribute('aria-pressed','false'));};
function applySurface(){model?.traverse(o=>{if(o.name.startsWith('portrait_hair_strands')||o.name.startsWith('feature_')||o.name.startsWith('detail_'))o.visible=!clay;if(o.isMesh)o.material=clay?clayMaterial:o.userData.studyMaterial;});}
$('surface').onclick=()=>{clay=!clay;applySurface();$('surface').setAttribute('aria-pressed',String(clay));$('surface').textContent=clay?'顯示五官材質':'檢查素模';};
$('version').onchange=load;$('framing').onclick=()=>{pitch=0;$('top-view').setAttribute('aria-pressed','false');whole=!whole;$('framing').setAttribute('aria-pressed',String(whole));$('framing').textContent=framingLabel();reset();};
$('motion').onclick=()=>{if(!ready||!actions.wave)return;if(playing){stopMotion();return;}playing=true;actions.wave?.reset().play();$('motion').setAttribute('aria-pressed','true');$('motion').textContent='暫停動作';};
$('guides').onchange=()=>document.body.classList.toggle('guides',$('guides').checked);
$('capture').onclick=()=>{if(!ready)return;renderer.render(scene,camera);canvas.toBlob(blob=>{if(!blob)return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`character-${version}-${whole?'full':'portrait'}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);},'image/png');};
canvas.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();setAngle(angle+(e.key==='ArrowLeft'?-.15:.15));}if(e.key==='Home')setAngle(-.16);});
matchMedia('(max-width:700px)').addEventListener('change',()=>{if(['director-v13','director-v14','director-v15'].includes(version)&&!whole)reset();});
new ResizeObserver(resize).observe(canvas.parentElement);const clock=new THREE.Clock();renderer.setAnimationLoop(()=>{const dt=Math.min(clock.getDelta(),.05);if(playing)mixer?.update(dt);controls.update();renderer.render(scene,camera);});reset();load();
window.hopeCharacterStudy={audit:()=>({ready,version,angle,pitch,whole,playing,clay,animationTime:mixer?.time||0,clips:Object.keys(actions),triangles:renderer.info.render.triangles,meshes:model?(()=>{let n=0;model.traverseVisible(o=>{if(o.isMesh)n++;});return n;})():0}),setAngle};
